from collections import deque

def distances(graph, start):
    result = {start: 0}
    pending = deque([start])
    while pending:
        room = pending.pop()
        for neighbor in graph.get(room, []):
            if neighbor not in result:
                result[neighbor] = result[room] + 1
                pending.append(neighbor)
    return result

